const log = find_block({ names: ['oak_log', 'birch_log', 'spruce_log'], max_distance: 32 });
if (!log) {
  return { done: false, detail: 'no log within 32 blocks' };
}
await dig(log.x, log.y, log.z);
const made = await craft('oak_planks', 1);
if (!made.ok) {
  return { done: false, detail: made.detail };
}
return { done: true, detail: 'mined a log and made planks' };
